def icon(name: str, size: int = 18, cls: str = "") -> str:
    """Return an inline <svg> for a Phosphor icon, coloured by CSS currentColor."""
    return (
        f'<svg class="ph {cls}" width="{size}" height="{size}" viewBox="0 0 256 256" '
        f'fill="currentColor" aria-hidden="true">{_PATHS[name]}</svg>'
    )
